import React, { useEffect, useRef } from "react";

const W = 600, H = 120, PAD = { top: 12, right: 16, bottom: 28, left: 36 };
const WINDOW = 60; // show last 60 data points

function buildPoints(alerts) {
  const bottles = alerts
    .filter(a => a.type !== "camera_alert")
    .slice(0, WINDOW)
    .reverse();
  return bottles;
}

export default function ConfidenceChart({ alerts }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const dpr = window.devicePixelRatio || 1;
    canvas.width  = W * dpr;
    canvas.height = H * dpr;
    ctx.scale(dpr, dpr);

    const pts    = buildPoints(alerts);
    const inner  = { w: W - PAD.left - PAD.right, h: H - PAD.top - PAD.bottom };

    ctx.clearRect(0, 0, W, H);

    // Background
    ctx.fillStyle = "#12141f";
    ctx.fillRect(0, 0, W, H);

    // Grid lines
    ctx.strokeStyle = "#2a2d3a";
    ctx.lineWidth = 0.5;
    [0.25, 0.5, 0.75, 1].forEach(v => {
      const y = PAD.top + inner.h * (1 - v);
      ctx.beginPath();
      ctx.moveTo(PAD.left, y);
      ctx.lineTo(PAD.left + inner.w, y);
      ctx.stroke();
      ctx.fillStyle = "#4b5563";
      ctx.font = "10px -apple-system, sans-serif";
      ctx.textAlign = "right";
      ctx.fillText(`${Math.round(v * 100)}%`, PAD.left - 4, y + 3);
    });

    if (pts.length === 0) {
      ctx.fillStyle = "#4b5563";
      ctx.font = "12px -apple-system, sans-serif";
      ctx.textAlign = "center";
      ctx.fillText("No detections yet", W / 2, H / 2);
      return;
    }

    // Plot line
    const xStep = inner.w / Math.max(pts.length - 1, 1);
    ctx.beginPath();
    ctx.strokeStyle = "#ef4444";
    ctx.lineWidth = 2;
    ctx.lineJoin = "round";

    pts.forEach((pt, i) => {
      const x = PAD.left + i * xStep;
      const y = PAD.top + inner.h * (1 - pt.confidence);
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    });
    ctx.stroke();

    // Fill under line
    ctx.lineTo(PAD.left + (pts.length - 1) * xStep, PAD.top + inner.h);
    ctx.lineTo(PAD.left, PAD.top + inner.h);
    ctx.closePath();
    ctx.fillStyle = "rgba(239,68,68,0.08)";
    ctx.fill();

    // Threshold line at 75%
    const ty = PAD.top + inner.h * 0.25;
    ctx.beginPath();
    ctx.strokeStyle = "#f59e0b";
    ctx.lineWidth = 1;
    ctx.setLineDash([4, 4]);
    ctx.moveTo(PAD.left, ty);
    ctx.lineTo(PAD.left + inner.w, ty);
    ctx.stroke();
    ctx.setLineDash([]);

    // Dots on each point
    pts.forEach((pt, i) => {
      const x = PAD.left + i * xStep;
      const y = PAD.top + inner.h * (1 - pt.confidence);
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fillStyle = "#ef4444";
      ctx.fill();
    });

    // X-axis time labels
    ctx.fillStyle = "#4b5563";
    ctx.font = "10px -apple-system, sans-serif";
    ctx.textAlign = "center";
    const step = Math.max(1, Math.floor(pts.length / 5));
    pts.forEach((pt, i) => {
      if (i % step !== 0) return;
      const x = PAD.left + i * xStep;
      const t = new Date(pt.timestamp).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
      ctx.fillText(t, x, H - 6);
    });

  }, [alerts]);

  const card = {
    background: "#1a1d27", borderRadius: 12,
    border: "1px solid #2a2d3a", overflow: "hidden", marginBottom: 16,
  };

  return (
    <div style={card}>
      <div style={{ padding: "12px 16px", borderBottom: "1px solid #2a2d3a",
                    display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <span style={{ fontSize: 13, fontWeight: 600, color: "#9ca3af", letterSpacing: 0.5 }}>
          CONFIDENCE OVER TIME
        </span>
        <div style={{ display: "flex", alignItems: "center", gap: 14, fontSize: 11, color: "#6b7280" }}>
          <span style={{ display: "flex", alignItems: "center", gap: 4 }}>
            <span style={{ width: 12, height: 2, background: "#ef4444", display: "inline-block" }} />
            Detection
          </span>
          <span style={{ display: "flex", alignItems: "center", gap: 4 }}>
            <span style={{ width: 12, height: 2, background: "#f59e0b", display: "inline-block",
                           borderTop: "2px dashed #f59e0b", height: 0 }} />
            75% threshold
          </span>
        </div>
      </div>
      <canvas
        ref={canvasRef}
        style={{ width: "100%", height: H, display: "block" }}
        role="img"
        aria-label="Confidence score over time for bottle detections"
      />
    </div>
  );
}
